INSERT INTO articles (id, slug, title, intro, details, steps, tips, documents,
                      fees, warning, source, tags, category, status,
                      seo_title, seo_description, last_update)
VALUES ('transcript-edevlet', 'transcript-edevlet', 'وثائق الطالب من e-Devlet: كشف الدرجات ووثيقة الطالب مجاناً وفوراً — ومتى يلزم الختم الرطب', 'كشف الدرجات (Transkript) ووثيقة الطالب (Öğrenci Belgesi) — أكثر وثيقتين يطلبهما أي ملف طلابي — تستخرجهما مجاناً خلال دقيقة من e-Devlet برمز تحقّق تقبله الجهات. هذا الدليل يريك الاستخراج، ومتى يبقى قلم الطلاب لازماً (الختم الرطب والصيغ الخاصة)، وإلى أين تذهب الوثيقتان فعلاً: التصديق، وإذن عمل الطالب، وإذن السفر الدراسي.', '<div style="background:#ecfdf5;border:2px solid #10b981;border-radius:12px;padding:18px 22px;margin:0 0 20px;"><p style="margin:0 0 10px;font-size:17px;"><strong>الخلاصة</strong></p><p style="margin:0;">وثيقتا الطالب الجامعي الأكثر طلباً — <strong>كشف الدرجات</strong> (<span dir="ltr">Transkript</span>) و<strong>وثيقة الطالب</strong> (<span dir="ltr">Öğrenci Belgesi</span>) — تستخرجهما <strong>مجاناً وفوراً</strong> من e-Devlet برمز تحقّق تقبله الجهات. لا طوابير قلم الطلاب إلا حين يُطلب ختمٌ رطب صراحةً.</p></div><h2>الاستخراج من e-Devlet</h2><ol><li>ابحث في e-Devlet عن <span dir="ltr">Transkript Belgesi Sorgulama</span> لكشف الدرجات، أو <span dir="ltr">Öğrenci Belgesi Sorgulama</span> لوثيقة الطالب.</li><li>اختر جامعتك وأنشئ الوثيقة — تصدر PDF <strong>برمز تحقّق</strong> تتثبّت به أي جهة من صحتها.</li><li>الخدمة تغطّي الجامعات المربوطة بمنظومة التعليم العالي — وأغلب الجامعات الحكومية والكثير من الخاصة مربوطة؛ إن لم تجد جامعتك فمرجعك قلم شؤون الطلاب (Öğrenci İşleri).</li></ol><h2>متى تحتاج قلم الطلاب رغم كل شيء؟</h2><ul><li>حين تشترط الجهة <strong>ختماً رطباً وتوقيعاً</strong> نصّاً — بعض القنصليات وجهات الخارج ما زالت تطلبه.</li><li>حين تحتاج صيغة خاصة (بالإنجليزية، أو بترويسة معيّنة، أو لسنوات محدّدة).</li><li>جامعتك غير مربوطة بالخدمة.</li></ul><h2>إلى أين تذهب هاتان الوثيقتان عادةً؟</h2><ul><li><strong>ملفات التصديق والتعادل</strong> نحو سوريا وغيرها — كشف الدرجات ركن الملف: <a href="/article/document-attestation-turkey-to-syria-students-2026">مسار التصديق للطلاب والخريجين</a>.</li><li><strong>إذن عمل الطالب</strong> — وثيقة الطالب من أساسياته: <a href="/article/work-permit-students">عمل الطلاب الأجانب</a>.</li><li><strong>إذن السفر الدراسي</strong> لحامل الكملك في جامعة وقفية — وثيقة استمرار الدراسة مع التقويم الأكاديمي: <a href="/article/travel-permit">دليل إذن السفر</a>.</li><li>المنح، والسكن الطلابي، وتخفيضات المواصلات — كلّها تسأل عن وثيقة الطالب.</li></ul><h2>أسئلة متكرّرة</h2><h3>تخرّجت — هل ما زلت أستخرج الكشف من e-Devlet؟</h3><p>وثيقة الطالب تنتهي بانتهاء القيد؛ أمّا كشف درجات الخرّيج وشهادته فبحسب ربط جامعتك — جرّب الخدمة، وإلا فقلم الطلاب/الخرّيجين في جامعتك.</p><h3>الجهة رفضت النسخة الإلكترونية؟</h3><p>رمز التحقّق حجّتك أولاً — فإن أصرّت على الرطب فهو حقّها الإجرائي: قلم الطلاب يصدره، وخذ أكثر من نسخة ما دمت هناك.</p>', ARRAY['ابحث في e-Devlet عن Transkript Belgesi أو Öğrenci Belgesi Sorgulama.', 'اختر جامعتك وأنشئ الوثيقة وحمّلها PDF برمز التحقّق.', 'جامعتك غير مربوطة أو الجهة تشترط ختماً رطباً؟ قلم شؤون الطلاب.', 'وجّه الوثيقة لغرضها: تصديق، إذن عمل طالب، إذن سفر دراسي، منح وسكن.', 'خذ نسخاً إضافية عند مراجعة القلم — توفّر مراجعات قادمة.']::text[], ARRAY['رمز التحقّق هو الوثيقة — أكثر الجهات لا تحتاج ورقة أصلاً.', 'مجانية وفورية — لا تدفع لوسيط «يستخرجها».', 'الختم الرطب حقّ إجرائي لبعض الجهات — لا تجادل، استخرجه من القلم.', 'وثيقة الطالب تنتهي بانتهاء القيد — استخرج حاجتك في وقتها.', 'لملف التصديق نحو سوريا: الكشف ركن الملف — راجع دليله قبل الترتيب.']::text[], ARRAY['حساب e-Devlet (برقمك الأجنبي أو التركي)', 'لا شيء آخر للإلكترونية — وهويتك لقلم الطلاب عند الرطب']::text[],
        'الاستخراج من e-Devlet مجاني بالكامل. ونسخ قلم الطلاب بحسب نظام جامعتك — وأكثرها مجاني أيضاً.', 'بعض الجهات (قنصليات وجهات خارجية) تشترط الختم الرطب نصاً — اقرأ متطلب جهتك قبل الاكتفاء بالإلكترونية. ووثيقة الطالب لا تصدر بعد انتهاء قيدك.', 'خدمتا Transkript Belgesi Sorgulama وÖğrenci Belgesi Sorgulama على بوابة e-Devlet (turkiye.gov.tr) للجامعات المربوطة بمنظومة التعليم العالي — وثائق مرمَّزة للتحقّق؛ وأقلام شؤون الطلاب للصيغ الورقية', ARRAY['كشف الدرجات', 'وثيقة الطالب', 'e-Devlet', 'الدراسة والتعليم', 'دليل', '2026']::text[], 'الدراسة والتعليم', 'approved',
        'كشف الدرجات ووثيقة الطالب من e-Devlet مجاناً — خلال دقيقة', 'Transkript وÖğrenci Belgesi برمز تحقّق تقبله الجهات، ومتى يبقى الختم الرطب لازماً — وإلى أين تذهب الوثيقتان: التصديق وإذن عمل الطالب وإذن السفر الدراسي.', CURRENT_DATE)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, intro = EXCLUDED.intro, details = EXCLUDED.details,
    steps = EXCLUDED.steps, tips = EXCLUDED.tips, documents = EXCLUDED.documents,
