    tags = EXCLUDED.tags, category = EXCLUDED.category, status = EXCLUDED.status,
    seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description,
    last_update = EXCLUDED.last_update;

INSERT INTO articles (id, slug, title, intro, details, steps, tips, documents,
                      fees, warning, source, tags, category, status,
                      seo_title, seo_description, last_update)
VALUES ('tomer-registration', 'tomer-registration', 'تعلّم التركية 2026: معاهد TÖMER من A1 إلى C1 — والبديل المجاني في مراكز التعليم الشعبي', 'C1 هي عتبة الدراسة الجامعية بالتركية — ومعاهد TÖMER الجامعية طريقها المعتاد: اختبار مستوى، فسلّم دورات، فشهادة. لكن قبل أن تدفع: تأكّد أن جامعتك المستهدفة تقبل شهادة معهدك، وقارن الرسوم بين المعاهد — واعرف البديل المجاني الذي لا يبيعه لك أحد: دورات مراكز التعليم الشعبي الحكومية لمن يريد اللغة للحياة والعمل.', '<div style="background:#ecfdf5;border:2px solid #10b981;border-radius:12px;padding:18px 22px;margin:0 0 20px;"><p style="margin:0 0 10px;font-size:17px;"><strong>الخلاصة</strong></p><p style="margin:0;">TÖMER معاهد اللغة التركية التابعة للجامعات: اختبار تحديد مستوى، ثم سلّم <span dir="ltr">A1–C1</span>، وشهادة <strong>C1</strong> هي العتبة المعتادة للدراسة الجامعية بالتركية. رسومها تتفاوت بين جامعة وأخرى — و<strong>البديل المجاني الذي لا يبيعه لك أحد</strong>: دورات مراكز التعليم الشعبي (Halk Eğitim) الحكومية.</p></div><h2>ما هو TÖMER — وكيف يعمل؟</h2><p>معاهد لتعليم التركية تتبع الجامعات (أشهرها تاريخياً معهد جامعة أنقرة، ولكل جامعة كبرى معهدها اليوم). المسار المعتاد:</p><ol><li><strong>اختبار تحديد مستوى</strong> يضعك في مستواك الحقيقي — لا تدفع لمستوى تجاوزته.</li><li><strong>السلّم الأوروبي A1 → C1</strong> على دورات (Kur) متتابعة.</li><li><strong>شهادة إتمام المستوى</strong> — وC1 هي المطلوبة عادةً للبرامج الجامعية الناطقة بالتركية أو للإعفاء من سنة اللغة.</li></ol><h2>قبل أن تدفع: ثلاثة أسئلة</h2><ul><li><strong>هل جامعتك المستهدفة تقبل شهادة هذا المعهد؟</strong> القبول شأن كل جامعة — اسأل قسم القبول في جامعتك <em>المستهدفة</em> قبل التسجيل في أي معهد.</li><li><strong>كم الرسم؟</strong> يتفاوت بين الجامعات ويتغيّر سنوياً — لا رقم ننشره؛ قارن بين معهدين أو ثلاثة في مدينتك.</li><li><strong>هل تحتاج C1 فعلاً؟</strong> برامج الإنجليزية لا تطلبها، وبعض الجهات يكفيها ما دون — حدّد هدفك قبل طريقك.</li></ul><h2>البديل المجاني: مراكز التعليم الشعبي (Halk Eğitim)</h2><p>مراكز حكومية في كل قضاء تقدّم دورات تركية <strong>مجانية</strong> بشهادات إتمام. ليست بديلاً مكافئاً لـC1 الجامعية في ملفات القبول عادةً، لكنها الطريق الأذكى لتعلّم اللغة للحياة والعمل بلا كلفة — واسأل مركز قضائك عن مواعيد الدورات. وللمهارات المهنية المجانية: <a href="/article/mesem-vocational-training-syrians-foreigners-turkey-2026">مراكز MESEM</a> و<a href="/article/btk-akademi-courses">منصة BTK Akademi</a>.</p><h2>وبعد اللغة؟</h2><p>الطريق الجامعي كاملاً عندنا: <a href="/article/private-universities-turkey-2026">الجامعات الخاصة</a>، و<a href="/article/scholarship-turkiye-burslari">منحة الحكومة التركية</a>، ولأولادك <a href="/article/school-registration-turkey">تسجيل المدارس</a>.</p><h2>أسئلة متكرّرة</h2><h3>كم تستغرق من الصفر إلى C1؟</h3><p>بحسب كثافة الدورات وانتظامك — المسار المتفرّغ أشهر عديدة لا أسابيع. من وعدك بـC1 في شهر يبيعك ورقة لا لغة.</p><h3>هل شهادة TÖMER تكفي للجنسية أو الإقامة؟</h3><p>لا شرط لغة عاماً في ملفات الإقامة الاعتيادية — والشهادة أداة قبول جامعي وعمل أساساً. لا تشترِ دورة لملفٍ لا يطلبها.</p>', ARRAY['حدّد هدفك أولاً: قبول جامعي بالتركية (تحتاج C1 غالباً) أم لغة للحياة والعمل؟', 'لهدف الجامعة: اسأل قسم القبول في جامعتك المستهدفة أي شهادات يقبل — قبل أي تسجيل.', 'قارن رسوم معهدين أو ثلاثة في مدينتك — تتفاوت وتتغيّر سنوياً.', 'قدّم لاختبار تحديد المستوى ولا تدفع لمستوى تجاوزته.', 'وللغة الحياة: اسأل مركز التعليم الشعبي في قضائك عن الدورات المجانية.', 'تابع بانتظام — C1 مسار أشهر لا أسابيع.']::text[], ARRAY['اختبار تحديد المستوى يوفّر عليك دورات كاملة — لا تبدأ من الصفر افتراضاً.', 'قبول الشهادة شأن الجامعة المستهدفة — اسألها هي لا المعهد.', 'دورات Halk Eğitim مجانية بشهادات — الأذكى لغير هدف القبول الجامعي.', 'برامج الإنجليزية لا تطلب C1 — لا تشترِ ما لا يطلبه ملفك.', 'من وعدك بـC1 في شهر يبيعك ورقة لا لغة.']::text[], ARRAY['جواز/كملك/إقامة للتسجيل', 'لمعاهد الجامعات: ما يطلبه المعهد (صور، رسوم الدورة)', 'لمراكز التعليم الشعبي: هويتك — والدورات مجانية']::text[],
        'رسوم معاهد TÖMER تتفاوت بين الجامعات وتتغيّر سنوياً — لا رقم ننشره؛ قارن بنفسك بين معاهد مدينتك. ودورات مراكز التعليم الشعبي مجانية.', 'لا تسجّل في معهد قبل سؤال جامعتك المستهدفة عن الشهادات المقبولة لديها. ولا شرط لغة عاماً لملفات الإقامة الاعتيادية — لا تشترِ دورة لملف لا يطلبها.', 'معاهد تعليم التركية الجامعية (TÖMER) وسلّم المستويات الأوروبي A1–C1 وشهادة C1 كعتبة معتادة للبرامج الناطقة بالتركية؛ ودورات اللغة التركية المجانية في مراكز التعليم الشعبي (Halk Eğitim Merkezleri) التابعة لوزارة التربية', ARRAY['TÖMER', 'تعلم التركية', 'الدراسة والتعليم', 'Halk Eğitim', 'دليل', '2026']::text[], 'الدراسة والتعليم', 'approved',
        'تعلم التركية: TÖMER حتى C1 — والبديل المجاني Halk Eğitim', 'C1 عتبة الدراسة بالتركية ومعاهد TÖMER طريقها — اختبار المستوى، ومقارنة الرسوم، وسؤال جامعتك المستهدفة أولاً. وللحياة والعمل: دورات مراكز التعليم الشعبي مجاناً.', CURRENT_DATE)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, intro = EXCLUDED.intro, details = EXCLUDED.details,
    steps = EXCLUDED.steps, tips = EXCLUDED.tips, documents = EXCLUDED.documents,
    fees = EXCLUDED.fees, warning = EXCLUDED.warning, source = EXCLUDED.source,
    tags = EXCLUDED.tags, category = EXCLUDED.category, status = EXCLUDED.status,
    seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description,
    last_update = EXCLUDED.last_update;

INSERT INTO articles (id, slug, title, intro, details, steps, tips, documents,
                      fees, warning, source, tags, category, status,
                      seo_title, seo_description, last_update)
VALUES ('btk-akademi-courses', 'btk-akademi-courses', 'BTK Akademi: دورات برمجة وتقنية مجانية بشهادات من منصة حكومية — بحساب e-Devlet', 'منصة حكومية تعطيك دورات برمجة وأمن معلومات ومهارات رقمية مجاناً بالكامل، بشهادة عند الإتمام، وتسجيل بحساب e-Devlet — تعمل برقمك الأجنبي كما بالتركي. قيدها الوحيد أنّ المحتوى بالتركية غالباً، وهذا نفسه تمرين لغة لمن بلغ مستوى متوسطاً. دليل مختصر صادق: ما تجده، وكيف تسجّل، وما قيمة الشهادة فعلاً.', '<div style="background:#ecfdf5;border:2px solid #10b981;border-radius:12px;padding:18px 22px;margin:0 0 20px;"><p style="margin:0 0 10px;font-size:17px;"><strong>الخلاصة</strong></p><p style="margin:0;"><span dir="ltr">BTK Akademi</span> منصة حكومية (تابعة لهيئة الاتصالات BTK) تقدّم دورات <strong>مجانية بشهادات</strong> — برمجة، وأمن معلومات، وتصميم، ومهارات رقمية. الدخول بحساب e-Devlet، والشهادة عند إتمام الدورة. قيدها الوحيد: المحتوى <strong>بالتركية غالباً</strong>.</p></div><h2>ما الذي تجده فيها؟</h2><ul><li>مسارات برمجة وتطوير (بايثون، جافا، ويب…) من الصفر إلى المتقدم.</li><li>أمن سيبراني، وشبكات، وذكاء اصطناعي، وتحليل بيانات.</li><li>مهارات رقمية عامة تصلح لكل باحث عمل.</li></ul><p>الدورات ذاتية الوتيرة: فيديوهات وتمارين، وشهادة إلكترونية عند الإتمام تضيفها إلى سيرتك.</p><h2>التسجيل</h2><ol><li>ادخل منصة <span dir="ltr">btkakademi.gov.tr</span>.</li><li>سجّل بحساب <strong>e-Devlet</strong> (يعمل برقمك الأجنبي كما بالتركي) أو بإنشاء حساب على المنصة.</li><li>اختر مسارك وابدأ — كل شيء مجاني.</li></ol><h2>قيمة الشهادة — بصراحة</h2><p>شهادة إتمام دورة، لا شهادة جامعية ولا رخصة مهنية: قيمتها في <strong>المهارة التي بنيتها</strong> وفي إظهار الجدّية على السيرة — خاصة لمن يدخل سوق العمل التقني بلا شهادة رسمية في المجال. ولا يبيعك أحد «شهادة BTK معتمدة» بمقابل — المنصة مجانية بالكامل.</p><h2>واللغة عائقك؟</h2><p>المحتوى بالتركية غالباً — وهو نفسه تمرين لغة ممتاز لمن بلغ مستوى متوسطاً. وإن كانت لغتك دون ذلك فابدأ من <a href="/article/tomer-registration">دورات التركية (TÖMER والتعليم الشعبي المجاني)</a> بالتوازي. وللتدريب المهني الحرفي: <a href="/article/mesem-vocational-training-syrians-foreigners-turkey-2026">مراكز MESEM</a>. ولمن يسأل عن العمل بعد المهارة: <a href="/article/work-permit-turkey-2026">دليل إذن العمل</a>.</p>', ARRAY['ادخل btkakademi.gov.tr وسجّل بحساب e-Devlet.', 'اختر مساراً يخدم هدفاً محدداً (وظيفة، مهارة) لا «دورات للتجميع».', 'تابع بوتيرتك وأتمّ التمارين — الشهادة عند الإتمام.', 'أضف المهارة والشهادة إلى سيرتك مع ما بنيته فعلاً.', 'لغتك دون المتوسط؟ وازِ الدورات بتعلم التركية.']::text[], ARRAY['مجانية بالكامل — من يبيعك «تسجيلاً» أو «شهادة معتمدة» بمقابل يحتال.', 'الشهادة قيمتها بالمهارة خلفها — أتمم التمارين لا الفيديوهات فقط.', 'المحتوى بالتركية غالباً — وهو تمرين لغة إضافي لا عائق فقط.', 'الدخول برقمك الأجنبي عبر e-Devlet يعمل.', 'للحِرَف اليدوية والمهن: مراكز MESEM هي البديل العملي.']::text[], ARRAY['حساب e-Devlet (أو حساب منصة جديد)', 'لا شيء آخر — لا رسوم ولا أوراق']::text[],
        'مجانية بالكامل: الدورات والشهادات والتسجيل. أي مقابل يُطلب منك باسم المنصة احتيال.', 'الشهادة شهادة إتمام دورة لا شهادة جامعية ولا رخصة مهنية — قيمتها بالمهارة التي بنيتها. والمحتوى بالتركية غالباً فقيّم مستواك قبل مسار متقدم.', 'منصة BTK Akademi الحكومية (btkakademi.gov.tr) التابعة لهيئة المعلومات والاتصالات BTK — دورات مجانية بشهادات إتمام، والدخول عبر e-Devlet', ARRAY['BTK Akademi', 'دورات مجانية', 'البرمجة', 'الدراسة والتعليم', 'دليل', '2026']::text[], 'الدراسة والتعليم', 'approved',
        'BTK Akademi: دورات تقنية مجانية بشهادات — بحساب e-Devlet', 'منصة حكومية: برمجة وأمن معلومات ومهارات رقمية مجاناً بالكامل بشهادات إتمام، والتسجيل بحساب e-Devlet برقمك الأجنبي — والمحتوى بالتركية غالباً، وقيمة الشهادة بصراحة.', CURRENT_DATE)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, intro = EXCLUDED.intro, details = EXCLUDED.details,
    steps = EXCLUDED.steps, tips = EXCLUDED.tips, documents = EXCLUDED.documents,
    fees = EXCLUDED.fees, warning = EXCLUDED.warning, source = EXCLUDED.source,
    tags = EXCLUDED.tags, category = EXCLUDED.category, status = EXCLUDED.status,
    seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description,
    last_update = EXCLUDED.last_update;

-- الطيّة الأخيرة
UPDATE articles SET status = 'draft', last_update = CURRENT_DATE
WHERE slug IN ('deportation-centers-rights') AND status = 'approved';

-- ═══════════════════════════════════════════════════════════════════════════
DO $check$
DECLARE n int;
BEGIN
    SELECT count(*) INTO n FROM articles
     WHERE slug = 'transcript-edevlet' AND status = 'approved' AND details LIKE '%Öğrenci Belgesi%';
    IF n <> 1 THEN RAISE EXCEPTION 'transcript rebuild did not land'; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'tomer-registration' AND status = 'approved' AND details LIKE '%Halk Eğitim%';
    IF n <> 1 THEN RAISE EXCEPTION 'tomer rebuild did not land'; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'btk-akademi-courses' AND status = 'approved' AND details LIKE '%btkakademi.gov.tr%';
    IF n <> 1 THEN RAISE EXCEPTION 'btk rebuild did not land'; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'detention-center-rights' AND status = 'approved' AND length(details) > 20000;
    IF n <> 1 THEN RAISE EXCEPTION 'the detention canonical is not intact'; END IF;

    SELECT count(*) INTO n FROM articles WHERE slug IN ('deportation-centers-rights') AND status = 'approved';
    IF n > 0 THEN RAISE EXCEPTION '% stub(s) still approved', n; END IF;
END
$check$;

SELECT 'student docs rebuilt (Transkript + Ogrenci Belgesi)' AS البند,
       (details LIKE '%Öğrenci Belgesi%')::text AS النتيجة
FROM articles WHERE slug = 'transcript-edevlet'
UNION ALL
SELECT 'tomer rebuilt (A1-C1 + the free Halk Egitim alternative)',
       (details LIKE '%Halk Eğitim%')::text
FROM articles WHERE slug = 'tomer-registration'
UNION ALL
SELECT 'btk rebuilt (free state platform, honest certificate value)',
       (details LIKE '%btkakademi.gov.tr%')::text
FROM articles WHERE slug = 'btk-akademi-courses'
UNION ALL
SELECT 'the 123-char scrap retired next to the 27K guide', count(*)::text
FROM articles WHERE slug IN ('deportation-centers-rights') AND status = 'approved';
